<?php

namespace App\Services\Evaluation\Integrated;

use App\Enums\LearningStateValue;
use App\Enums\NextLearningActionType;

/**
 * Independently authored expectation for an end-to-end integrated NEXUS path
 * (M6-07).
 *
 * INDEPENDENCE CONTRACT: authored from the M6-07 specification and the documented
 * cross-layer contract, never generated by executing the NEXUS pipeline. Optional
 * terminal expectations left null are not asserted; the universal cross-layer
 * invariants (linkage, provenance completeness, task-demand consistency, privacy,
 * no causal claim) are always enforced by the comparator.
 */
final readonly class ExpectedIntegration
{
    /**
     * @param  list<LearningStateValue>  $acceptableTerminalStates
     * @param  list<NextLearningActionType>  $acceptableNextActions
     */
    public function __construct(
        public ?LearningStateValue $terminalState = null,
        public array $acceptableTerminalStates = [],
        public ?NextLearningActionType $nextAction = null,
        public array $acceptableNextActions = [],
        public ?bool $expectIntervention = null,
        public bool $expectRetryConsumesSameIntervention = false,
        public ?bool $expectReassessmentEligible = null,
        public bool $expectReassessmentSourceOfTruthUnchanged = false,
        public bool $expectGracefulFailure = false,
        public ?string $expectedFailureStatus = null,
        public bool $expectUpstreamIntactAfterFailure = false,
        public bool $ambiguous = false,
        public string $rationale = '',
    ) {}

    /**
     * @return array<string, mixed>
     */
    public function toArray(): array
    {
        return [
            'terminal_state' => $this->terminalState?->value,
            'acceptable_terminal_states' => array_map(fn (LearningStateValue $s): string => $s->value, $this->acceptableTerminalStates),
            'next_action' => $this->nextAction?->value,
            'acceptable_next_actions' => array_map(fn (NextLearningActionType $a): string => $a->value, $this->acceptableNextActions),
            'expect_intervention' => $this->expectIntervention,
            'expect_retry_consumes_same_intervention' => $this->expectRetryConsumesSameIntervention,
            'expect_reassessment_eligible' => $this->expectReassessmentEligible,
            'expect_reassessment_source_of_truth_unchanged' => $this->expectReassessmentSourceOfTruthUnchanged,
            'expect_graceful_failure' => $this->expectGracefulFailure,
            'expected_failure_status' => $this->expectedFailureStatus,
            'expect_upstream_intact_after_failure' => $this->expectUpstreamIntactAfterFailure,
            'ambiguous' => $this->ambiguous,
            'rationale' => $this->rationale,
        ];
    }
}
